<script setup lang="ts">import { computed,ref } from 'vue'; import SectionHeader from '../components/SectionHeader.vue'; import EmptyState from '../components/EmptyState.vue'; import { useTerminalStore } from '../stores/terminal'; const store=useTerminalStore(); const filter=ref('all'); const rows=computed(()=>store.trades.filter((t:any)=>filter.value==='all'||String(t.side||t.posSide).toLowerCase().includes(filter.value))); const signed=(v:any)=>`${Number(v||0)>=0?'+':''}${Number(v||0).toFixed(2)}`</script>
<template><section class="panel p-3 min-[380px]:p-4 sm:p-5"><SectionHeader title="生命周期交易台账" subtitle="开仓、平仓、手续费与归因审计" :count="rows.length"><template #actions><div class="flex gap-1"><button v-for="x in [{v:'all',n:'全部'},{v:'long',n:'多单'},{v:'short',n:'空单'}]" :key="x.v" class="btn !min-h-9 !px-2 !py-1" :class="filter===x.v?'!border-blue-500 text-brand':''" @click="filter=x.v">{{ x.n }}</button></div></template></SectionHeader><div v-if="rows.length" class="hidden overflow-x-auto md:block"><table class="terminal-table font-mono"><thead><tr><th>标的 / 杠杆</th><th>方向</th><th>策略</th><th>开仓</th><th>平仓</th><th>保证金</th><th class="text-right">净盈亏</th><th>离场归因</th></tr></thead><tbody><tr v-for="(t,i) in rows" :key="t.id||i"><td><b>{{ t.inst||t.instId||'--' }}</b> <span class="badge">{{ t.lever||'3x' }}</span></td><td><span class="badge" :class="String(t.side||t.posSide).toLowerCase().includes('long')?'badge-profit':'badge-loss'">{{ t.side||t.posSide||'--' }}</span></td><td>{{ t.strategy||'--' }}</td><td>{{ t.open_time||'--' }}</td><td>{{ t.close_time||'持仓中' }}</td><td>{{ Number(t.margin||t.margin_usdt||0).toFixed(2) }} U</td><td class="text-right"><span class="data-pill" :class="Number(t.pnl)>=0?'data-pill-profit':'data-pill-loss'"><b>{{ signed(t.pnl) }} U</b></span></td><td class="muted">{{ t.exit_reason||t.status||'--' }}</td></tr></tbody></table></div><div v-if="rows.length" class="grid gap-2.5 md:hidden"><article v-for="(t,i) in rows" :key="t.id||i" class="subpanel p-3"><div class="flex items-start justify-between gap-2"><div><b class="font-mono text-sm">{{ t.inst||t.instId||'--' }}</b><span class="badge ml-2">{{ t.lever||'3x' }}</span><p class="mt-1 text-[10px] muted">{{ t.strategy||'--' }}</p></div><span class="badge" :class="String(t.side||t.posSide).toLowerCase().includes('long')?'badge-profit':'badge-loss'">{{ t.side||t.posSide||'--' }}</span></div><div class="mt-3 space-y-2 border-t divider pt-3 text-[11px] font-mono"><div class="flex justify-between gap-3"><span class="muted">开仓</span><b class="text-right">{{ t.open_time||'--' }}</b></div><div class="flex justify-between gap-3"><span class="muted">平仓</span><b class="text-right">{{ t.close_time||'持仓中' }}</b></div><div class="flex justify-between"><span class="muted">保证金</span><b>{{ Number(t.margin||t.margin_usdt||0).toFixed(2) }} U</b></div><div class="flex justify-between"><span class="muted">净盈亏</span><span class="data-pill" :class="Number(t.pnl)>=0?'data-pill-profit':'data-pill-loss'"><b>{{ signed(t.pnl) }} U</b></span></div></div><p class="mt-3 border-t divider pt-3 text-[10px] muted">{{ t.exit_reason||t.status||'--' }}</p></article></div><EmptyState v-else text="无匹配交易台账记录"/></section></template>
